// CUDA WebShader 0.1.1. Generated from kernel water_step.
@group(0) @binding(0) var<storage, read> b_input: array<vec4<f32>>;
@group(0) @binding(1) var<storage, read> b_flux: array<vec4<f32>>;
@group(0) @binding(2) var<storage, read_write> b_output: array<vec4<f32>>;
struct CWParams {
  p_n: i32,
  cw_pad_4: u32,
  cw_pad_8: u32,
  cw_pad_12: u32,
}
@group(0) @binding(3) var<uniform> cw_params: CWParams;
const cw_block_size: vec3<u32> = vec3<u32>(128u, 1u, 1u);



alias cw_f64 = vec2<u32>;










struct CWDoubleParts { significand: vec2<u32>, exponent: i32, }

// Input has its leading bit at bit 55 and three guard/round/sticky bits.














// Restoring square root: 56 root bits include guard/round/sticky for binary64.



















@compute @workgroup_size(128, 1, 1)
fn main(
  @builtin(local_invocation_id) cw_thread: vec3<u32>,
  @builtin(workgroup_id) cw_block: vec3<u32>,
  @builtin(num_workgroups) cw_grid: vec3<u32>
) {
  var v_i: i32 = i32(((cw_block.x * cw_block_size.x) + cw_thread.x));
  if ((v_i >= (cw_params.p_n * cw_params.p_n))) {
    return;
  }
  var v_x: i32 = (v_i % cw_params.p_n);
  var v_z: i32 = (v_i / cw_params.p_n);
  var v_p: vec4<f32> = b_input[v_i];
  var v_f: vec4<f32> = b_flux[v_i];
  var v_w: f32 = ((((v_p.y - v_f.x) - v_f.y) - v_f.z) - v_f.w);
  if ((v_x > 0i)) {
    v_w = (v_w + b_flux[(v_i - 1i)].y);
  }
  if ((v_x < (cw_params.p_n - 1i))) {
    v_w = (v_w + b_flux[(v_i + 1i)].x);
  }
  if ((v_z > 0i)) {
    v_w = (v_w + b_flux[(v_i - cw_params.p_n)].w);
  }
  if ((v_z < (cw_params.p_n - 1i))) {
    v_w = (v_w + b_flux[(v_i + cw_params.p_n)].z);
  }
  v_p.y = max(0.0f, v_w);
  b_output[v_i] = v_p;
}
